import type { EngineInterface, Register } from 'claude-code'

// The ClaudePet app listens on a Unix socket; every request stays on this machine.
const SOCKET = 'Library/Application Support/ClaudePet/pet.sock'
// Holds "1" after `/pet quit`, so no session relaunches the app until `/pet`.
const PAUSED = 'Library/Application Support/ClaudePet/paused'
const APP = 'Applications/ClaudePet.app'
const BASE = 'http://claudepet'

const FLUSH_MS = 150
const INBOX_MS = 2000
const RELAUNCH_MS = 20_000
const MAX_QUEUE = 300
const LIVE_CHARS = 240

const HELP = [
  '/pet 用法：',
  '  /pet              显示宠物并同步本会话（未运行时启动）',
  '  /pet hide         隐藏宠物',
  '  /pet list         展开会话列表',
  '  /pet size 小|中|大  调整大小（也可用 s|m|l）',
  '  /pet bubble on|off 开关活动气泡',
  '  /pet sound on|off  开关声音提示',
  '  /pet reset        回到屏幕右下角',
  '  /pet status       查看状态',
  '  /pet quit         退出 ClaudePet（输入 /pet 重新启动）',
].join('\n')

const ACTIONS = ['show', 'hide', 'list', 'size', 'bubble', 'sound', 'reset', 'status', 'quit']

type PetEvent = { type: string; agent?: string; [field: string]: unknown }
type Live = { kind: 'thinking' | 'text'; text: string; agent?: string; isDirty: boolean }

// The module's own state: a reload starts it over, and session.start fills it again.
const bridge = {
  home: '',
  session: '',
  cwd: '',
  host: undefined as string | undefined,
  model: undefined as string | undefined,
  isConnected: false,
  needsHello: true,
  isFlushing: false,
  lastLaunch: 0,
  queue: [] as PetEvent[],
  live: new Map<string, Live>(),
}

function pushLive() {
  for (const l of bridge.live.values()) {
    if (!l.isDirty) continue
    bridge.queue.push({ type: l.kind, text: l.text, agent: l.agent })
    l.isDirty = false
  }
}

function trimQueue() {
  const { queue } = bridge
  if (queue.length > MAX_QUEUE) queue.splice(0, queue.length - MAX_QUEUE)
}

function enqueue(ev: PetEvent) {
  pushLive()
  bridge.queue.push(ev)
  trimQueue()
}

// Streamed text is coalesced: the app gets the latest tail once per flush, not every token.
function stream(agent: string | undefined, kind: Live['kind'], piece: string) {
  const key = agent ?? ''
  let l = bridge.live.get(key)
  if (l === undefined || l.kind !== kind) {
    pushLive()
    l = { kind, text: '', agent, isDirty: false }
    bridge.live.set(key, l)
  }
  l.text = (l.text + piece).slice(-LIVE_CHARS)
  l.isDirty = true
}

async function isPaused($: EngineInterface) {
  try {
    return (await $.fs.read(`${bridge.home}/${PAUSED}`)).trim() === '1'
  } catch {
    return false
  }
}

async function setPaused($: EngineInterface, paused: boolean) {
  try {
    await $.fs.write(`${bridge.home}/${PAUSED}`, paused ? '1' : '')
  } catch {
    // No support folder yet: the app has never run, so nothing is paused.
  }
}

async function launch($: EngineInterface) {
  const now = Date.now()
  if (bridge.home === '' || now - bridge.lastLaunch < RELAUNCH_MS) return
  bridge.lastLaunch = now
  if (await isPaused($)) return
  try {
    await $.process.run(['/usr/bin/open', '-g', '-a', `${bridge.home}/${APP}`])
  } catch {
    // Not installed: stay quiet, the session goes on without a pet.
  }
}

async function request($: EngineInterface, method: string, path: string, body?: unknown) {
  const res = await $.http.fetch(`${BASE}${path}`, {
    method,
    socketPath: `${bridge.home}/${SOCKET}`,
    headers: { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  if (!res.ok) throw new Error(`ClaudePet answered ${res.status}`)
  return res.text
}

// Asks the app to act on a `/pet` subcommand; undefined when it is not running.
async function control($: EngineInterface, action: string, value: string) {
  try {
    const text = await request($, 'POST', '/control', { action, value })
    return JSON.parse(text) as { ok?: boolean; message?: string }
  } catch {
    return undefined
  }
}

async function runPet($: EngineInterface, args: string) {
  const [word = 'show', ...rest] = args.trim().split(/\s+/).filter(Boolean)
  const action = word.toLowerCase()
  if (action === 'help' || action === '-h' || action === '--help') return HELP
  if (!ACTIONS.includes(action)) return `未知子命令「${word}」。\n\n${HELP}`

  if (action === 'show') {
    await setPaused($, false)
    let answer = await control($, action, '')
    if (answer === undefined) {
      bridge.lastLaunch = 0
      await launch($)
      for (let i = 0; i < 20 && answer === undefined; i += 1) {
        await $.clock.sleep(250)
        answer = await control($, action, '')
      }
    }
    if (answer === undefined) return 'ClaudePet 启动失败：请确认 ~/Applications/ClaudePet.app 存在。'
    bridge.needsHello = true
    await flush($)
    return answer.message ?? 'ClaudePet 已显示。'
  }

  if (action === 'quit') await setPaused($, true)
  const answer = await control($, action, rest.join(' '))
  if (answer === undefined) {
    return action === 'quit' ? 'ClaudePet 没有在运行。' : 'ClaudePet 没有在运行，输入 /pet 启动。'
  }
  return answer.message ?? ''
}

async function flush($: EngineInterface) {
  pushLive()
  const { session, cwd, host, model } = bridge
  if (bridge.isFlushing || session === '' || (bridge.queue.length === 0 && !bridge.needsHello)) return
  bridge.isFlushing = true
  const events = bridge.queue.splice(0, bridge.queue.length)
  if (bridge.needsHello) events.unshift({ type: 'hello', model })
  try {
    await request($, 'POST', '/events', { session, cwd, host, events })
    bridge.isConnected = true
    bridge.needsHello = false
  } catch {
    bridge.isConnected = false
    bridge.needsHello = true
    // Keep what was not delivered (minus the hello) for when the app is back.
    bridge.queue.unshift(...events.filter(ev => ev.type !== 'hello'))
    trimQueue()
    void launch($)
  } finally {
    bridge.isFlushing = false
  }
}

async function pollInbox($: EngineInterface) {
  if (bridge.session === '' || !bridge.isConnected) return
  try {
    const text = await request($, 'GET', `/inbox?session=${encodeURIComponent(bridge.session)}`)
    const { messages } = JSON.parse(text) as { messages?: string[] }
    for (const message of messages ?? []) {
      await $.prompt.submit({ text: message, asUser: true })
      $.ui.toast('ClaudePet: 已提交来自桌宠的回复')
    }
  } catch {
    bridge.isConnected = false
    bridge.needsHello = true
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    bridge.home = (await $.env.get('HOME')) ?? ''
    bridge.session = await $.session.id()
    bridge.cwd = e.cwd
    bridge.model = await $.session.model()
    bridge.host = (await $.env.get('__CFBundleIdentifier')) ?? (await $.env.get('TERM_PROGRAM'))
    bridge.needsHello = true
    bridge.queue.length = 0
    bridge.live.clear()

    $.clock.every(FLUSH_MS, () => void flush($))
    $.clock.every(INBOX_MS, () => void pollInbox($))
    await $.command.register({
      name: 'pet',
      description: '控制 ClaudePet 桌宠：显示、隐藏、会话列表、大小、气泡、声音、退出',
      argumentHint: '[show|hide|list|size|bubble|sound|reset|status|quit|help]',
      immediate: true,
    })
    void flush($)

    return result
  })

  on('command.run', { command: 'pet' }, async ($, e) => ({ text: await runPet($, e.args) }))

  on('session.end', async ($, e, next) => {
    enqueue({ type: 'end', reason: e.reason })
    await flush($)
    return next(e)
  })

  on('prompt.submit', ($, e, next) => {
    if (e.isMeta !== true) {
      const text = e.command === undefined ? e.text : `/${e.command.name} ${e.command.args ?? ''}`
      enqueue({ type: 'prompt', text: text.slice(0, 500) })
    }
    return next(e)
  })

  on('turn.start', ($, e, next) => {
    bridge.live.delete(e.agentId ?? '')
    enqueue({
      type: 'turn.start',
      agent: e.agentId,
      text: e.agentId === undefined ? undefined : e.text.slice(0, 200),
    })
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    for await (const chunk of next(e)) {
      if (chunk.kind === 'thinking') stream(e.agentId, 'thinking', chunk.text)
      else if (chunk.kind === 'text') stream(e.agentId, 'text', chunk.text)
      else if (chunk.kind === 'tool') enqueue({ type: 'tool.prep', tool: chunk.name, agent: e.agentId })
      yield chunk
    }
  })

  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    const startedAt = Date.now()
    enqueue({ type: 'tool.start', tool, id: e.tool_use_id, detail: describe(tool, e), agent: e.agentId })
    const result = await next(e)
    enqueue({
      type: 'tool.end',
      tool,
      id: e.tool_use_id,
      agent: e.agentId,
      ok: result.deny === undefined && result.isError !== true,
      denied: result.deny !== undefined,
      ms: Date.now() - startedAt,
    })
    return result
  }).catch(($, e, next) => next(e))

  on('classic.PermissionRequest', ($, e, next) => {
    enqueue({ type: 'permission', tool: e.tool_name, detail: describe(e.tool_name, e.tool_input) })
    return next(e)
  })

  on('classic.PermissionDenied', ($, e, next) => {
    enqueue({ type: 'denied' })
    return next(e)
  })

  on('classic.Notification', ($, e, next) => {
    enqueue({ type: 'notification', kind: e.notification_type, text: e.message.slice(0, 300) })
    return next(e)
  })

  on('classic.PreCompact', ($, e, next) => {
    enqueue({ type: 'compact' })
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    bridge.live.delete(e.agentId ?? '')
    enqueue({ type: 'turn.end', agent: e.agentId, reason: e.reason, text: result.text.slice(0, 1500) })
    return result
  })
}

// A short, human label for what a tool call is about.
function describe(tool: string, input: unknown): string {
  const a = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>
  const str = (key: string) => (typeof a[key] === 'string' ? (a[key] as string) : '')
  const base = (path: string) => path.split('/').filter(Boolean).pop() ?? path
  const line = (text: string) => (text.split('\n')[0] ?? '').trim().slice(0, 120)

  switch (tool) {
    case 'Bash':
    case 'PowerShell':
      return line(str('command'))
    case 'Read':
    case 'Edit':
    case 'Write':
    case 'MultiEdit':
      return base(str('file_path'))
    case 'NotebookEdit':
      return base(str('notebook_path'))
    case 'Glob':
    case 'Grep':
      return line(str('pattern'))
    case 'WebFetch':
      return str('url').replace(/^https?:\/\//, '').split('/')[0] ?? ''
    case 'WebSearch':
      return line(str('query'))
    case 'Agent':
    case 'Task':
      return line(str('description') || str('subagent_type'))
    case 'Skill':
      return str('skill')
    case 'TodoWrite':
      return Array.isArray(a.todos) ? `${a.todos.length} 项` : ''
    case 'AskUserQuestion':
      return Array.isArray(a.questions) && a.questions.length > 0
        ? line(String((a.questions[0] as Record<string, unknown>).question ?? ''))
        : ''
  }
  if (tool.startsWith('mcp__')) {
    const [, server, name] = tool.split('__')
    return `${server} · ${name}`
  }
  return line(str('description') || str('file_path') || str('path') || str('pattern') || str('url'))
}

